from pathlib import Path
import pyarrow.dataset as ds,pandas as pd,json,time
root=Path('video-agent-studio/episodes/capital-10eok-map-20261017/research/source-completion-v1');files=[str(p) for p in Path('staged/trade').rglob('*.parquet')];dataset=ds.dataset(files,format='parquet');cols=['apt_id','apt_seq','jibun','sigungu_code','legal_dong_code','legal_dong_name','apt_name_raw','apt_name_norm','road_address','deal_date','deal_amount','area_m2','floor','build_year','is_canceled','cancel_date','__filename'];table=dataset.to_table(columns=cols,filter=(ds.field('area_m2')>=83)&(ds.field('area_m2')<85));df=table.to_pandas();df['source_filtered_item_index']=df.groupby('__filename').cumcount();df=df.rename(columns={'__filename':'source_file'});df.to_parquet(root/'staged_84_source_rows.parquet',index=False);s={'rows':len(df),'cancelled':int(df.is_canceled.fillna(False).sum()),'invalid_price':int(df.deal_amount.le(0).sum()),'files':len(files),'multiplicity_preserved':True,'source_index_basis':'staged file row position within 83<=area<85 filter, not raw original item position','source_file_and_filtered_index_unique':not df.duplicated(['source_file','source_filtered_item_index']).any()};(root/'staged_source_summary.json').write_text(json.dumps(s,indent=2),encoding='utf8');print(json.dumps(s))
